import pytest

if pytest.use_correct:
    from correct_python_programs.to_base import to_base
else:
    from python_programs.to_base import to_base


def test_attack_1():
    # docstring example: checks digit order and uppercase
    assert to_base(31, 16) == "1F"


def test_attack_2():
    # power of base: trailing zeros become leading zeros if reversed
    assert to_base(8, 2) == "1000"


def test_attack_3():
    # base-10 identity must preserve most-significant-first order
    assert to_base(12345, 10) == "12345"


def test_attack_4():
    # binary non-palindrome: reversed would be 0101
    assert to_base(10, 2) == "1010"


def test_attack_5():
    # two-digit with zero: reversed would be 01
    assert to_base(36, 36) == "10"


def test_attack_6():
    # mixed letters, order matters and must be uppercase: reversed is EF
    assert to_base(254, 16) == "FE"


def test_attack_7():
    # base-36 multi-digit letters: reversed would be AY
    assert to_base(1234, 36) == "YA"


def test_attack_8():
    # single digit must be exact single char, no extra padding/reversal
    assert to_base(7, 10) == "7"
    assert to_base(15, 16) == "F"
    assert to_base(35, 36) == "Z"
    assert isinstance(to_base(31, 16), str)
